Searching for keywords: nuclear, nuclear energy, nuclear power, fission, reactor. Code:

from functions import extract_pdf_text
p='IPCC_AR6_SYR_LongerReport.pdf'
kw=['nuclear','nuclear energy','nuclear power','fission','reactor']
found=[]; ctx={}
for i in range(81):
    t=extract_pdf_text(p, page_number=i)
    low=t.lower()
    if any(k in low for k in kw):
        found.append(i+1)
        # grab a line containing the keyword
        line=''
        for k in kw:
            if k in low:
                for seg in t.split('\n'):
                    if k in seg.lower():
                        line=seg.strip(); break
                break
        ctx[i+1]=line
print('Pages:', found)
for pg in found:
    print(pg, ctx.get(pg,'(no context)'))
